text:
Laboratorio: amplía tu vocabulario emocional


Laboratorio · se ejecuta en tu navegador

Elige la familia de lo que sientes y su intensidad. El laboratorio te propone palabras más precisas y una pregunta para afinar.

seleccion = window.Lab.seleccion
rango = window.Lab.rango
viewof familia = seleccion("Familia de la emoción", ["Miedo", "Enfado", "Tristeza", "Vergüenza", "Alegría", "Interés"], {value: "Miedo"})
viewof intensidad = rango("Intensidad", [1, 3], {value: 2, formato: x =&gt; ["baja", "media", "alta"][x - 1]})






























{
  const V = {
    "Miedo": [["inquietud", "preocupación", "incertidumbre"], ["ansiedad", "nerviosismo", "aprensión"], ["pánico", "angustia", "terror"], "¿Qué es lo que temes que ocurra, en concreto?"],
    "Enfado": [["fastidio", "impaciencia", "molestia"], ["irritación", "frustración", "indignación"], ["rabia", "ira", "furia"], "¿Qué objetivo o qué valor sientes que se ha bloqueado o vulnerado?"],
    "Tristeza": [["melancolía", "desánimo", "nostalgia"], ["decepción", "pena", "desaliento"], ["desesperanza", "abatimiento", "desolación"], "¿Qué has perdido o qué esperabas que no ha ocurrido?"],
    "Vergüenza": [["incomodidad", "timidez", "apuro"], ["bochorno", "culpa", "inseguridad"], ["humillación", "sentirse fuera de lugar", "indignidad"], "¿Es por algo que hiciste (culpa) o por cómo te ves (vergüenza)?"],
    "Alegría": [["satisfacción", "tranquilidad", "agrado"], ["entusiasmo", "orgullo", "gratitud"], ["euforia", "júbilo", "exaltación"], "¿Qué ha salido bien y qué papel has tenido tú?"],
    "Interés": [["curiosidad", "atención", "intriga"], ["motivación", "implicación", "fascinación"], ["absorción", "pasión", "flujo"], "¿Qué te gustaría descubrir ahora?"]
  };
  const [b, m, a, q] = V[familia], pal = [b, m, a][intensidad - 1];
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;p&gt;Palabras más precisas para &lt;strong&gt;${familia.toLowerCase()}&lt;/strong&gt; de intensidad ${["baja", "media", "alta"][intensidad - 1]}:&lt;/p&gt;
   &lt;p style="font-size:1.25rem"&gt;${pal.map(w =&gt; `&lt;span class="badge text-bg-light border me-1"&gt;${w}&lt;/span&gt;`).join("")}&lt;/p&gt;
   &lt;p&gt;&lt;strong&gt;Para afinar:&lt;/strong&gt; ${q}&lt;/p&gt;
   &lt;p class="small"&gt;Prueba a completar: «Siento ___ porque ___, y lo que necesito es ___».${intensidad === 3 && ["Miedo", "Tristeza", "Vergüenza"].includes(familia) ? ' Si sientes esto con intensidad alta durante días, habla con alguien de confianza o con un profesional (ver &lt;a href="90-recursos.html"&gt;Recursos de apoyo&lt;/a&gt;).' : ""}&lt;/p&gt;`;
  return d;
}

Laboratorio: tu plan si-entonces


Laboratorio · se ejecuta en tu navegador; tu texto no sale de él


texto = window.Lab.texto
seleccion = window.Lab.seleccion
viewof sit = texto("Si… (situación previsible)", {value: "recibo un correo con la decisión de la revista"})
viewof emo = texto("…y probablemente sienta…", {value: "ansiedad y miedo al rechazo"})
viewof estr = seleccion("Familia de estrategia", ["Selección de la situación", "Modificación de la situación", "Despliegue de la atención", "Cambio cognitivo (reevaluación)", "Modulación de la respuesta"], {value: "Selección de la situación"})
viewof acc = texto("…entonces haré…", {value: "leerlo por la mañana, con tiempo, y no responder hasta el día siguiente"})












































{
  const esc = s =&gt; (s || "").replace(/&/g, "&amp;").replace(/&lt;/g, "&lt;");
  const consejo = {
    "Selección de la situación": "Útil cuando puedes elegir el momento o el contexto. Cuidado con convertirla en evitación sistemática.",
    "Modificación de la situación": "Cambia algo de la situación: pide un orden del día, una pausa, un acompañante.",
    "Despliegue de la atención": "Dirige la atención a lo útil o a lo que depende de ti. Distraerse un rato ayuda en emociones intensas.",
    "Cambio cognitivo (reevaluación)": "Prepara la frase alternativa por adelantado: con la emoción alta cuesta inventarla.",
    "Modulación de la respuesta": "Respiración lenta, movimiento, una pausa antes de responder. Evita suprimir sin más."
  }[estr];
  const vaga = (acc || "").trim().split(/\s+/).length &lt; 4;
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;blockquote style="font-size:1.1rem"&gt;&lt;strong&gt;Si&lt;/strong&gt; ${esc(sit)} y siento ${esc(emo)}, &lt;strong&gt;entonces&lt;/strong&gt; ${esc(acc)}.&lt;/blockquote&gt;
   &lt;p&gt;&lt;strong&gt;${estr}:&lt;/strong&gt; ${consejo}&lt;/p&gt;
   ${vaga ? '&lt;p class="lab-medio" style="font-weight:600"&gt;La acción es muy breve o vaga: concreta qué harás, cuándo y dónde.&lt;/p&gt;' : '&lt;p class="lab-bien" style="font-weight:600"&gt;Plan concreto. Escríbelo donde lo veas en el momento en que lo necesitarás.&lt;/p&gt;'}`;
  return d;
}

Laboratorio: tu encaje en las seis áreas


Laboratorio · herramienta de reflexión, no de diagnóstico · nada sale de tu navegador

Valora tu situación actual en cada área de Maslach y Leiter, de −2 (gran desajuste) a +2 (buen encaje).

rango = window.Lab.rango
viewof a1 = rango("Carga de trabajo: es asumible con mis horas y recursos", [-2, 2], {value: -1})
viewof a2 = rango("Control: puedo decidir sobre cómo y cuándo hago mi trabajo", [-2, 2], {value: 1})
viewof a3 = rango("Recompensa: mi esfuerzo se reconoce", [-2, 2], {value: 0})
viewof a4 = rango("Comunidad: me siento apoyado o apoyada por mi entorno", [-2, 2], {value: -1})
viewof a5 = rango("Equidad: las decisiones que me afectan son justas", [-2, 2], {value: 1})
viewof a6 = rango("Valores: lo que hago tiene sentido para mí", [-2, 2], {value: 2})



















































{
  const ar = [["Carga de trabajo", a1, "Revisa con tu dirección prioridades y plazos; di que no a lo que no es esencial."], ["Control", a2, "Negocia márgenes de decisión: horarios, orden de tareas, métodos."],
    ["Recompensa", a3, "Haz visibles tus avances y celebra los hitos, también los pequeños."], ["Comunidad", a4, "Busca o crea espacios de apoyo: grupos de escritura, asociaciones de doctorandos."],
    ["Equidad", a5, "Pide criterios explícitos (autoría, asignación de tareas) y usa los cauces institucionales si hace falta."], ["Valores", a6, "Reconecta con por qué empezaste; si el desajuste es profundo, vale la pena replantearse el camino."]];
  const W = 300, x0 = 150;
  const barras = ar.map(([n, v], i) =&gt; { const w = Math.abs(v) * 60, x = v &lt; 0 ? x0 - w : x0, c = v &lt; 0 ? "#eb6834" : "#2a78d6";
    return `&lt;text x="${x0 - 128}" y="${i * 32 + 21}" font-size="12" fill="currentColor"&gt;${n}&lt;/text&gt;${v ? `&lt;rect x="${x + 128}" y="${i * 32 + 8}" width="${w - 2}" height="18" rx="3" fill="${c}"/&gt;` : ""}&lt;text x="${v &lt; 0 ? x + 122 : x + 134 + w}" y="${i * 32 + 21}" font-size="12" text-anchor="${v &lt; 0 ? "end" : "start"}" fill="currentColor"&gt;${v &gt; 0 ? "+" + v : v}&lt;/text&gt;`; }).join("");
  const mal = ar.filter(a =&gt; a[1] &lt; 0).sort((p, q) =&gt; p[1] - q[1]);
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;svg viewBox="10 0 440 ${ar.length * 32 + 8}" width="100%" style="max-width:520px" role="img" aria-label="Encaje en las seis áreas de la vida laboral"&gt;&lt;line x1="${x0 + 128}" y1="0" x2="${x0 + 128}" y2="${ar.length * 32}" stroke="currentColor" opacity=".4"/&gt;${barras}&lt;/svg&gt;
   ${mal.length ? `&lt;p&gt;&lt;strong&gt;Áreas con desajuste:&lt;/strong&gt;&lt;/p&gt;&lt;ul&gt;${mal.map(([n, v, s]) =&gt; `&lt;li&gt;&lt;strong&gt;${n}&lt;/strong&gt; (${v}). ${s}&lt;/li&gt;`).join("")}&lt;/ul&gt;` : '&lt;p class="lab-bien" style="font-weight:600"&gt;No señalas desajustes ahora. Anota qué lo hace posible para protegerlo.&lt;/p&gt;'}
   ${mal.length &gt;= 4 ? '&lt;p class="lab-medio" style="font-weight:600"&gt;Varias áreas con desajuste a la vez aumentan el riesgo de agotamiento. Es un buen momento para hablarlo con alguien de confianza o con el servicio de atención psicológica de tu universidad.&lt;/p&gt;' : ""}
   &lt;p class="small"&gt;Esta herramienta no mide tu salud mental ni sustituye una valoración profesional.&lt;/p&gt;`;
  return d;
}

Laboratorio: responder como a un buen amigo


Laboratorio · se ejecuta en tu navegador; tu texto no sale de él

Escribe un pensamiento autocrítico frecuente. El laboratorio te ayuda a reformularlo con los tres componentes de Neff.

texto = window.Lab.texto
viewof critico = texto("Pensamiento autocrítico", {value: "Todos mis compañeros publican más que yo; no valgo para esto", submit: "Reformular"})
















{
  const esc = s =&gt; (s || "").replace(/&/g, "&amp;").replace(/&lt;/g, "&lt;");
  const t = (critico || "").toLowerCase();
  const marcas = [["siempre", "generalización"], ["nunca", "generalización"], ["todos", "comparación global"], ["nadie", "generalización"], ["no valgo", "juicio sobre la identidad"], ["soy un", "juicio sobre la identidad"], ["soy una", "juicio sobre la identidad"], ["fraude", "etiqueta de impostor"], ["inútil", "etiqueta"], ["desastre", "etiqueta"], ["debería", "exigencia rígida"]].filter(([w]) =&gt; t.includes(w));
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `${marcas.length ? `&lt;p&gt;Detecto: ${[...new Set(marcas.map(m =&gt; m[1]))].join(", ")}.&lt;/p&gt;` : ""}
   &lt;ol&gt;
    &lt;li&gt;&lt;strong&gt;Atención plena&lt;/strong&gt; (nombra lo que sientes, sin etiquetarte): «Ahora mismo me siento ___ porque ___».&lt;/li&gt;
    &lt;li&gt;&lt;strong&gt;Humanidad compartida&lt;/strong&gt;: «Muchas personas en el doctorado sienten esto; ___ (alguien que admiras) también ha pasado por algo parecido».&lt;/li&gt;
    &lt;li&gt;&lt;strong&gt;Amabilidad&lt;/strong&gt;: ¿qué le dirías a un buen amigo que pensara «${esc(critico)}»? Escríbelo y díselo a ti.&lt;/li&gt;
   &lt;/ol&gt;
   &lt;p class="small"&gt;Si este tipo de pensamientos es constante e intenso, o afecta a tu sueño y a tu vida diaria, coméntalo con un profesional (ver &lt;a href="90-recursos.html"&gt;Recursos de apoyo&lt;/a&gt;).&lt;/p&gt;`;
  return d;
}

Laboratorio: construye una retroalimentación


Laboratorio · se ejecuta en tu navegador; tu texto no sale de él


texto = window.Lab.texto
viewof sci = {
  const c = html`&lt;div&gt;&lt;/div&gt;`, campos = [["s", "Situación", "En el borrador del capítulo 2"], ["c", "Comportamiento", "eres muy desordenado y siempre dejas las referencias sin revisar"], ["i", "Impacto", "he tardado dos horas en comprobar las citas"], ["p", "Petición", "¿puedes usar el gestor de referencias en el capítulo 3?"]];
  const ins = campos.map(([k, et, v]) =&gt; { const t = texto(et, {value: v}); t.addEventListener("input", e =&gt; e.stopPropagation()); c.append(t); return [k, t]; });
  const b = html`&lt;button type="button" class="btn btn-primary btn-sm mt-1"&gt;Revisar&lt;/button&gt;`; c.append(b);
  const leer = () =&gt; Object.fromEntries(ins.map(([k, t]) =&gt; [k, t.value.trim()]));
  c.value = leer(); b.onclick = () =&gt; { c.value = leer(); c.dispatchEvent(new Event("input", {bubbles: true})); };
  return c;
}
















{
  const esc = s =&gt; (s || "").replace(/&/g, "&amp;").replace(/&lt;/g, "&lt;");
  const todo = `${sci.s} ${sci.c} ${sci.i}`.toLowerCase();
  const avisos = [];
  if (/\b(eres|eres un|eres una|tu actitud|tu forma de ser|tu personalidad)\b/.test(todo)) avisos.push("Hablas de la persona («eres…», «tu actitud»): descríbelo como una conducta observable (Kluger y DeNisi, 1996).");
  if (/\b(siempre|nunca|todo el rato|constantemente)\b/.test(todo)) avisos.push("Generalizas («siempre», «nunca»): céntrate en una situación concreta.");
  if (/\b(desordenad|vag[oa]|descuidad|irresponsable|perezos|incompetente)/.test(todo)) avisos.push("Usas un adjetivo valorativo: cámbialo por lo que hizo o dejó de hacer.");
  if (!sci.i) avisos.push("Falta el impacto: explica la consecuencia.");
  if (!sci.p) avisos.push("Falta la petición: di qué esperas a partir de ahora.");
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;blockquote&gt;${esc(sci.s)}, ${esc(sci.c)}, y ${esc(sci.i)}. ${esc(sci.p)}&lt;/blockquote&gt;
   ${avisos.length ? `&lt;ul&gt;${avisos.map(a =&gt; `&lt;li class="lab-medio" style="font-weight:600"&gt;${a}&lt;/li&gt;`).join("")}&lt;/ul&gt;` : '&lt;p class="lab-bien" style="font-weight:600"&gt;Centrada en la tarea, concreta y con una petición clara.&lt;/p&gt;'}`;
  return d;
}
